-module(typespec).
-export([main/0, area/1, describe/1]).

-type shape() :: {circle, number()} | {rect, number(), number()}.
-spec area(shape()) -> number().
area({circle, R}) -> math:pi() * R * R;
area({rect, W, H}) -> W * H.

-spec describe(term()) -> binary().
describe(X) when is_integer(X) -> <<"整数">>;
describe(X) when is_float(X) -> <<"浮点数">>;
describe(X) when is_binary(X) -> <<"二进制">>;
describe(X) when is_list(X) -> <<"列表">>;
describe(_) -> <<"其他">>.

main() ->
    io:format("~p~n", [area({rect, 3, 4})]),
    io:format("~p~n", [describe(3.14)]).

-module(branching).
-export([main/0, grade/1, classify/1]).

grade(Score) when Score >= 90 -> excellent;
grade(Score) when Score >= 60 -> pass;
grade(_) -> fail.

classify(X) ->
    case X of
        {error, Reason} -> {failed, Reason};
        {ok, Value} when is_integer(Value) -> {number, Value};
        {ok, Value} -> {other, Value}
    end.

main() ->
    io:format("~p~n", [grade(95)]),
    io:format("~p~n", [classify({ok, 7})]),
    io:format("~p~n", [classify({error, timeout})]),
    %% if 必须有 true 兜底
    X = 42,
    Level = if
                X =:= 0 -> zero;
                true -> nonzero
            end,
    io:format("~p~n", [Level]).
